using System;using System.IO;using System.Linq;using System.Text;using System.Collections.Generic;using System.Globalization;using System.Xml.Linq;
namespace V15Voice {
public sealed class RepairTake {
 public string Text="",VoiceKey="",Voice="",Signature="",Audio="",NaturalAudio="",Hash="",NaturalHash="",Reason="";public double Natural,Measured,Speed,SpeechSeconds,Tail;public bool Success;public List<Cue> Cues=new List<Cue>();
 public string Describe(double start){return "Giọng: "+Voice+"\r\nTrước căn: "+Natural.ToString("0.000")+"s · sau căn: "+Measured.ToString("0.000")+"s\r\nTốc độ: "+Speed.ToString("0.000")+"× · kết thúc lời ≈ "+Scripts.Stamp(start+SpeechSeconds)+"\r\nNghỉ cuối: "+Tail.ToString("0.000")+"s\r\n"+(Success?"Đạt khung":"Chưa đạt")+" · "+Reason;}
}
public sealed class RepairPart {
 public AnchorStage Stage;public double WindowEnd;public string Audio="",Hash="",Voice="",Text="";public RepairTake A,B,Selected;
 public bool HasAudio{get{return RepairSession.Valid(Audio,Hash);}}
}
public sealed class RepairSession {
 public string Source="",SourceHash="",Folder="",Stamp="",Settings="",Signature="",Output="",Report="";public bool Anchored;public List<Cue> PublishedCues=new List<Cue>();public List<Cue> Sources=new List<Cue>();public List<RepairPart> Parts=new List<RepairPart>();
 public static string H(string text){return SpeechArchive.Hash(text??"");}
 public static bool Valid(string path,string hash){try{return File.Exists(path)&&hash.Length>0&&StateFiles.Hash(path)==hash&&FinalAudio.PcmFrames(path)>0;}catch{return false;}}
 public static List<AnchorStage> Plan(List<Cue> cues,bool anchored){Scripts.Validate(cues);return anchored?AnchoredVoice.Plan(cues):cues.Select((c,i)=>new AnchorStage{Number=i+1,Cues=new List<Cue>{c}}).ToList();}
 static XElement CueXml(Cue c){return new XElement("cue",new XAttribute("id",c.Id),new XAttribute("start",c.Start),new XAttribute("end",c.End),new XAttribute("speaker",c.Speaker??""),new XAttribute("anchor",c.AnchorAfter?1:0),c.Text);}
 static List<Cue> ReadCues(XElement x){return x.Elements("cue").Select(c=>new Cue{Id=StateFiles.I(c,"id"),Start=StateFiles.D(c,"start"),End=StateFiles.D(c,"end"),Text=c.Value,Speaker=StateFiles.S(c,"speaker"),AnchorAfter=StateFiles.I(c,"anchor")==1}).ToList();}
 string Local(string name){return name.Length>0&&name==Path.GetFileName(name)&&name!="."&&name!=".."?Path.Combine(Folder,name):"";}
 public static RepairSession Open(string source,List<Cue> cues,string state,bool anchored){
  Scripts.Validate(cues);if(cues.Any(c=>c.Prose))throw new Exception("A/B timeline cần SRT có mốc. TXT vẫn dùng tạo voice tự nhiên.");
  var p=new RepairSession{Source=Path.GetFullPath(source),SourceHash=StateFiles.Hash(source),Sources=VoiceRenderReport.Snapshot(cues),Anchored=anchored,Folder=Path.Combine(state,"audio-repair",H(Path.GetFullPath(source).ToLowerInvariant()+"|"+anchored))};
  p.Stamp=H(p.SourceHash+"|"+String.Join(";",cues.Select(c=>c.Id+":"+c.Start.ToString("R",CultureInfo.InvariantCulture)+":"+c.End.ToString("R",CultureInfo.InvariantCulture)+":"+c.AnchorAfter)));
  var x=StateFiles.Read(Path.Combine(p.Folder,"session.xml"));bool restore=x!=null&&StateFiles.S(x,"stamp")==p.Stamp;
  if(restore){p.Sources=ReadCues(x.Element("sources"));if(x.Element("published")!=null)p.PublishedCues=ReadCues(x.Element("published"));p.Settings=StateFiles.S(x,"settings");p.Signature=StateFiles.S(x,"signature");p.Output=StateFiles.S(x,"output");p.Report=StateFiles.S(x,"report");}
  p.Parts=Plan(p.Sources,anchored).Select(s=>new RepairPart{Stage=s,Text=s.Text}).ToList();for(int i=0;i<p.Parts.Count;i++)p.Parts[i].WindowEnd=i+1<p.Parts.Count?p.Parts[i+1].Stage.Start:p.Parts[i].Stage.End;
  if(restore)foreach(var row in x.Elements("part")){int i=StateFiles.I(row,"n")-1;if(i<0||i>=p.Parts.Count)continue;var s=p.Parts[i];s.Audio=p.Local(StateFiles.S(row,"audio"));s.Hash=StateFiles.S(row,"hash");s.Voice=StateFiles.S(row,"voice");s.Text=StateFiles.S(row,"text",s.Stage.Text);s.A=p.ReadTake(row.Element("A"));s.B=p.ReadTake(row.Element("B"));s.Selected=p.ReadTake(row.Element("selected"));}
  return p;
 }
 RepairTake ReadTake(XElement x){if(x==null||StateFiles.S(x,"audio").Length==0)return null;return new RepairTake{Text=StateFiles.S(x,"text"),VoiceKey=StateFiles.S(x,"voiceKey"),Voice=StateFiles.S(x,"voice"),Signature=StateFiles.S(x,"signature"),Audio=Local(StateFiles.S(x,"audio")),NaturalAudio=Local(StateFiles.S(x,"naturalAudio")),Hash=StateFiles.S(x,"hash"),NaturalHash=StateFiles.S(x,"naturalHash"),Reason=StateFiles.S(x,"reason"),Success=StateFiles.I(x,"success")==1,Natural=StateFiles.D(x,"natural"),Measured=StateFiles.D(x,"measured"),Speed=StateFiles.D(x,"speed"),SpeechSeconds=StateFiles.D(x,"speech"),Tail=StateFiles.D(x,"tail"),Cues=ReadCues(x)};}
 XElement TakeXml(string name,RepairTake t){if(t==null)return new XElement(name);var x=new XElement(name,new XAttribute("text",t.Text),new XAttribute("voiceKey",t.VoiceKey),new XAttribute("voice",t.Voice),new XAttribute("signature",t.Signature),new XAttribute("audio",Path.GetFileName(t.Audio)),new XAttribute("naturalAudio",Path.GetFileName(t.NaturalAudio)),new XAttribute("hash",t.Hash),new XAttribute("naturalHash",t.NaturalHash),new XAttribute("reason",t.Reason),new XAttribute("success",t.Success?1:0),new XAttribute("natural",t.Natural),new XAttribute("measured",t.Measured),new XAttribute("speed",t.Speed),new XAttribute("speech",t.SpeechSeconds),new XAttribute("tail",t.Tail));foreach(var c in t.Cues)x.Add(CueXml(c));return x;}
 public void Save(){var x=new XElement("audioRepair",new XAttribute("schema",1),new XAttribute("source",Source),new XAttribute("stamp",Stamp),new XAttribute("settings",Settings),new XAttribute("signature",Signature),new XAttribute("output",Output),new XAttribute("report",Report),new XElement("sources",Sources.Select(CueXml)),new XElement("published",PublishedCues.Select(CueXml)));foreach(var s in Parts)x.Add(new XElement("part",new XAttribute("n",s.Stage.Number),new XAttribute("audio",Path.GetFileName(s.Audio)),new XAttribute("hash",s.Hash),new XAttribute("voice",s.Voice),new XAttribute("text",s.Text),TakeXml("A",s.A),TakeXml("B",s.B),TakeXml("selected",s.Selected)));StateFiles.Write(Path.Combine(Folder,"session.xml"),x);}
 public void Validate(){if(StateFiles.Hash(Source)!=SourceHash)throw new Exception("File SRT nguồn đã đổi. Đóng A/B và nhập lại file trước khi áp dụng.");}
 public List<Cue> Effective(){return Parts.SelectMany(s=>s.Selected!=null&&s.Selected.Success?s.Selected.Cues:s.Stage.Cues).Select(c=>new Cue{Id=c.Id,Start=c.Start,End=c.End,Text=c.Text,Speaker=c.Speaker,AnchorAfter=c.AnchorAfter}).ToList();}
 public RepairPart At(int cueIndex){int cursor=0;foreach(var s in Parts){if(cueIndex<cursor+s.Stage.Cues.Count)return s;cursor+=s.Stage.Cues.Count;}throw new Exception("Chọn một câu hợp lệ.");}
 public static void Capture(string source,List<Cue> cues,string state,bool anchored,string settings,KokoroEngine e,RenderOptions o,string wav){
  var p=Open(source,cues,state,anchored);p.Sources=VoiceRenderReport.Snapshot(cues);p.PublishedCues=new List<Cue>();p.Output="";p.Parts=Plan(p.Sources,anchored).Select(s=>new RepairPart{Stage=s,Text=s.Text,Voice=e.VoiceName}).ToList();p.Settings=settings;p.Signature=AudioRepair.Signature(e,o);Directory.CreateDirectory(p.Folder);
  using(var input=File.OpenRead(wav)){if(FinalAudio.PcmFrames(wav)!=(long)Math.Round(cues.Last().End*24000))throw new Exception("WAV nền không khớp timeline.");for(int i=0;i<p.Parts.Count;i++){var s=p.Parts[i];s.WindowEnd=i+1<p.Parts.Count?p.Parts[i+1].Stage.Start:s.Stage.End;int samples=checked((int)Math.Round((s.WindowEnd-s.Stage.Start)*24000));var bytes=new byte[samples*2];input.Position=44+(long)Math.Round(s.Stage.Start*24000)*2;int read=0;while(read<bytes.Length){int n=input.Read(bytes,read,bytes.Length-read);if(n==0)throw new EndOfStreamException();read+=n;}var data=new short[samples];Buffer.BlockCopy(bytes,0,data,0,bytes.Length);s.Audio=Path.Combine(p.Folder,Guid.NewGuid().ToString("N")+".wav");new Wave{Rate=24000,Samples=data}.Write(s.Audio);s.Hash=StateFiles.Hash(s.Audio);}}
  p.Validate();p.Save();
 }
}
public static class AudioRepair {
 static string F(double d){return d.ToString("R",CultureInfo.InvariantCulture);}
 public static RenderOptions Options(string xml){var s=VoiceSettings.From(XElement.Parse(xml));return new RenderOptions{Anchored=s.Mode==2,Locked=s.Mode!=2,BaseSpeed=s.Speed,MinSpeed=s.MinSpeed,MaxSpeed=s.MaxSpeed,GentleFit=s.GentleFit,SlowShort=s.Slow,Gap=s.Gap,Punctuation=(PunctuationMode)s.Punctuation,CommaPause=s.CommaPause,StopPause=s.StopPause,QuestionPause=s.QuestionPause,ParagraphPause=s.ParagraphPause,Breathing=(BreathMode)s.Breathing,BreathPath=s.BreathPath,BreathLevel=s.BreathLevel/100,BreathEvery=s.BreathEvery,NormalizeLoudness=s.Normalize,TargetLufs=s.TargetLufs};}
 public static string Signature(KokoroEngine e,RenderOptions o){return RepairSession.H(String.Join("|",new[]{"repair209-v1",SpeechArchive.Key(e,"repair-profile",o.BaseSpeed),File.Exists(e.ReferencePath)?StateFiles.Hash(e.ReferencePath):"",F(o.BaseSpeed),F(o.MinSpeed),F(o.MaxSpeed),o.GentleFit.ToString(),o.SlowShort.ToString(),o.Punctuation.ToString(),F(o.CommaPause),F(o.StopPause),F(o.QuestionPause),F(o.ParagraphPause),F(o.Gap),o.Breathing.ToString(),F(o.BreathLevel),o.BreathEvery.ToString(),File.Exists(o.BreathPath)?StateFiles.Hash(o.BreathPath):"",o.NormalizeLoudness.ToString(),F(o.TargetLufs)}));}
 public static bool Matches(RepairTake t,KokoroEngine e,RenderOptions o,List<Cue> cues){return t!=null&&t.Signature==Signature(e,o)&&t.Text==String.Join(" ",cues.Select(c=>c.Text.Trim()))&&RepairSession.Valid(t.Audio,t.Hash)&&RepairSession.Valid(t.NaturalAudio,t.NaturalHash);}
 public static RepairTake Trial(RepairSession p,RepairPart part,KokoroEngine e,RenderOptions o,string voiceKey,List<Cue> words,string slot){
  o.Anchored=p.Anchored;o.TargetSeconds=0;var prior=e.RunReport;var report=new VoiceRenderReport(p.Sources,e,o,OutputFiles.Beside(p.Source));o.RunReport=report;e.RunReport=report;report.Stages.Clear();p.Report=report.PathName;string work=Path.Combine(p.Folder,"work-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(work);
  try{p.Validate();words=VoiceRenderReport.Snapshot(words);Scripts.Validate(words);for(int i=0;i<Math.Min(words.Count,part.Stage.Cues.Count);i++)words[i].Id=part.Stage.Cues[i].Id;if(words.Count!=part.Stage.Cues.Count||words.Where((c,i)=>c.Start!=part.Stage.Cues[i].Start||c.End!=part.Stage.Cues[i].End).Any())throw new Exception("Bản thử phải giữ nguyên mốc nguồn.");var s=new AnchorStage{Number=part.Stage.Number,Cues=words};if(s.Text.Length>20000)throw new Exception("Chặng tối đa 20.000 ký tự.");report.BeginStage(s);e.CheckFiles();Tempo.Validate(o);Punctuation.Validate(o);var units=new List<AnchorUnit>();Wave natural=AnchoredVoice.ReadStage(s,e,o,new BreathTrack(o,e.Root),work,units);report.StageNatural(natural.Duration);
   var stretch=new RenderOptions{BaseSpeed=o.BaseSpeed,MinSpeed=o.SlowShort?o.MinSpeed:o.BaseSpeed,MaxSpeed=o.MaxSpeed,GentleFit=o.GentleFit,RunReport=o.RunReport};var fit=AnchoredVoice.Fit(natural,s.Budget,stretch,e.Root,work,()=>e.Cancelled);double missing=Math.Max(0,s.Budget-fit.Audio.Duration);if(!p.Anchored&&!fit.Success&&missing>0&&missing<=Math.Min(.75,s.Budget*.2)){var exact=new short[(int)Math.Round(s.Budget*24000)];Array.Copy(fit.Audio.Samples,exact,fit.Audio.Samples.Length);fit.Audio=new Wave{Rate=24000,Samples=exact};fit.Success=true;fit.Reason="Nghỉ cuối cue Khóa SRT "+missing.ToString("0.000")+"s (tối đa 0.75s và 20% cue); không phải lời nói.";}
   report.StageDone(s,fit);if(e.Cancelled)throw new OperationCanceledException();string stem=Path.Combine(p.Folder,Guid.NewGuid().ToString("N"));natural.Write(stem+"-natural.wav");fit.Audio.Write(stem+".wav");double speech=Math.Max(0,fit.Audio.Duration-Punctuation.EdgeSilence(fit.Audio,false));
   var t=new RepairTake{VoiceKey=voiceKey,Voice=e.VoiceName,Signature=Signature(e,o),Text=s.Text,Cues=VoiceRenderReport.Snapshot(words),Audio=stem+".wav",NaturalAudio=stem+"-natural.wav",Natural=natural.Duration,Measured=fit.Measured,Speed=fit.Speed,SpeechSeconds=speech,Tail=Math.Max(0,s.Budget-speech),Success=fit.Success,Reason=fit.Reason};t.Hash=StateFiles.Hash(t.Audio);t.NaturalHash=StateFiles.Hash(t.NaturalAudio);if(slot=="A")part.A=t;else if(slot=="B")part.B=t;report.Finish(fit.Success?"ĐO A/B · CHƯA GHÉP WAV":"ĐO A/B · CHƯA KHỚP KHUNG","",fit.Success?null:new Exception(fit.Reason));p.Save();return t;
  }catch(Exception ex){report.Finish(ex is OperationCanceledException?"ĐÃ DỪNG":"THẤT BẠI","",ex);throw;}finally{e.RunReport=prior;try{Directory.Delete(work,true);}catch{}}
 }
 public static string Merge(RepairSession p,KokoroEngine e,RenderOptions o,Action<int,string> progress){
  string sig=Signature(e,o);o.Anchored=p.Anchored;o.Prose=false;o.TargetSeconds=0;o.AiRepair=null;o.Translation=null;if(o.ReportContext==null)o.ReportContext=new VoiceReportContext{SourcePath=p.Source,SourceCues=p.Sources,Purpose="Ghép A/B từ PCM đã lưu"};
  var prior=e.RunReport;var report=new VoiceRenderReport(p.Sources,e,o,OutputFiles.Beside(p.Source));e.RunReport=report;o.RunReport=report;report.Stages.Clear();p.Report=report.PathName;string temp=Path.Combine(p.Folder,"merge-"+Guid.NewGuid().ToString("N")+".wav");var notes=new StringBuilder("\r\nSỬA AUDIO / A-B 2.0.9\r\nGiọng nền: "+e.VoiceName+"\r\nCân âm tổng có thể thay đổi mức âm của toàn bài.\r\n");
  try{p.Validate();if(p.Signature.Length>0&&p.Signature!=sig)throw new Exception("Thiết lập/giọng nền đã đổi. Tạo lại WAV nền với thiết lập hiện tại trước khi ghép.");int bad=0;foreach(var s in p.Parts){if(e.Cancelled)throw new OperationCanceledException();progress((s.Stage.Number-1)*80/p.Parts.Count,"Chuẩn bị "+s.Stage.Number+"/"+p.Parts.Count);var t=s.Selected;if(t!=null){if(!t.Success||!RepairSession.Valid(t.Audio,t.Hash))throw new Exception("Bản đã chọn bị thiếu/hỏng hoặc chưa đạt ở chặng "+s.Stage.Number);if(t.Reason.StartsWith("Nghỉ đệm cuối")&&(p.Anchored||t.Tail>Math.Min(.75,s.Stage.Budget*.2)+.02))throw new Exception("NEEDS_REVIEW: bản A/B cũ dùng đệm đuôi quá giới hạn; đo lại chặng "+s.Stage.Number);notes.AppendLine("Chặng "+s.Stage.Number+" cue "+String.Join(",",s.Stage.Cues.Select(c=>c.Id))+" · ĐÃ CHỌN A/B\r\nLời dùng: "+t.Text+"\r\n"+t.Describe(s.Stage.Start));}
    else if(s.HasAudio){notes.AppendLine("Chặng "+s.Stage.Number+" · dùng lại audio nền · giọng "+s.Voice+" · "+Scripts.Stamp(s.Stage.Start)+" → "+Scripts.Stamp(s.Stage.End)+" · thời lượng TTS tự nhiên chưa đo riêng.");}
    else {try{t=Trial(p,s,e,Options(p.Settings),"nền",s.Stage.Cues,"");if(t.Success){s.Selected=t;p.Save();}else{bad++;notes.AppendLine("Chặng "+s.Stage.Number+" chưa đạt: "+t.Reason);}}catch(OperationCanceledException){throw;}catch(Exception ex){bad++;notes.AppendLine("Chặng "+s.Stage.Number+" lỗi TTS: "+ex.Message);}}
   }
   foreach(var part in p.Parts){var row=report.BeginStage(part.Stage);if(part.Selected!=null&&RepairSession.Valid(part.Selected.Audio,part.Selected.Hash)){var take=part.Selected;row.Text=take.Text;report.StageNatural(take.Natural);report.StageDone(part.Stage,new AnchorFit{Natural=take.Natural,Measured=take.Measured,Speed=take.Speed,Success=take.Success,Reason=take.Reason,Audio=Wave.Read(take.Audio)});}else{row.Status=part.HasAudio?"Dùng lại WAV nền":"Chưa có audio đạt";row.Reason="Không có số đo TTS riêng; xem ghi chú cuối báo cáo.";report.CurrentStage=null;}string words=part.Selected!=null?part.Selected.Text:part.Text;var used=part.Selected!=null?part.Selected.Cues:part.Stage.Cues;if(words!=String.Join(" ",used.Select(c=>c.Text.Trim())))throw new Exception("Lời metadata A/B không trùng cue thực tế; đo lại chặng "+part.Stage.Number);report.Units.Add(new VoiceReportUnit{Number=report.Units.Count+1,Stage=part.Stage.Number,CueIds=used.Select(c=>c.Id).ToList(),Text=words,Voice=part.Selected!=null?part.Selected.Voice:part.Voice,VoiceKey=part.Selected!=null?part.Selected.VoiceKey:"",Status="Dùng PCM đã lưu; lời khớp snapshot",Detail="Không suy đoán mốc audio từng cue từ chặng hoặc nền đã cắt.",CacheCalls=1,ExactMap=false});notes.AppendLine("\r\nPhạm vi "+Scripts.Stamp(part.Stage.Start)+" → "+Scripts.Stamp(part.Stage.End)+" · cue "+String.Join(",",part.Stage.Cues.Select(c=>c.Id))+"\r\nLời gốc: "+part.Stage.Text);if(part.Selected!=null)notes.AppendLine("Lời dùng: "+part.Selected.Text+"\r\n"+part.Selected.Describe(part.Stage.Start));}if(bad>0)throw new Exception("Chưa ghép WAV: "+bad+" chặng còn lỗi. Bản đạt được lưu; sửa chặng lỗi rồi ghép lại.");
   using(var w=new StreamingWave(temp,24000)){foreach(var s in p.Parts){if(e.Cancelled)throw new OperationCanceledException();w.At(s.Stage.Start,Wave.Read(s.Selected!=null?s.Selected.Audio:s.Audio));}w.Finish(p.Sources.Last().End);}
   long frames=(long)Math.Round(p.Sources.Last().End*24000);if(FinalAudio.PcmFrames(temp)!=frames)throw new Exception("WAV ghép lệch số mẫu.");if(o.NormalizeLoudness){FinalAudio.Normalize(e.Root,temp,temp+".norm.wav",frames,o.TargetLufs,()=>e.Cancelled,e.ReportActivity);File.Copy(temp+".norm.wav",temp,true);}if(e.Cancelled)throw new OperationCanceledException();p.Validate();var final=p.Effective();e.ReleaseModels();report.Step("TRANSLATE","Dịch Việt theo lời A/B đã chọn");o.Translation=OfflineTranslation.Run(final,o.Translator,String.IsNullOrEmpty(o.TranslationCacheRoot)?Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),"V15VoiceStudio","translation-cache"):o.TranslationCacheRoot,()=>e.Cancelled,(n,m)=>progress(95+n/20,m),p.Source);if(e.Cancelled)throw new OperationCanceledException();o.ReportContext.UserNote+=(o.ReportContext.UserNote.Length>0?"\r\n":"")+notes;p.Output=StableArtifacts.Publish(temp,OutputFiles.Beside(p.Source),final,o,report);p.PublishedCues=final;p.Signature=sig;p.Save();progress(100,(o.Translation.Complete?"Đã ghép WAV/SRT/TXT đồng bộ: ":"TRANSLATION_INCOMPLETE · WAV đạt, bộ chưa hoàn thiện: ")+p.Output);return p.Output;
  }catch(Exception ex){report.Finish(ex is OperationCanceledException?"ĐÃ DỪNG":"THẤT BẠI","",ex);throw;}finally{e.RunReport=prior;o.RunReport=report;p.Report=report.PathName;try{if(report.PathName!=Path.ChangeExtension(p.Output,null)+".voice-report.txt")File.AppendAllText(report.PathName,notes.ToString());}catch{}try{File.Delete(temp);File.Delete(temp+".norm.wav");}catch{}p.Save();}
 }
}
}
